import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { supabase } from '@/lib/supabase'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Upload, Link, CheckCircle, AlertCircle, Info } from 'lucide-react'
import { CsvImport } from './CsvImport'
import { UrlImport } from './UrlImport'
import { ImportResults } from './ImportResults'
import type { ParsedGearItem } from '@/utils/csvParser'
import type { GearItem } from '@/types/database'

interface ImportGearFormProps {
  onImportComplete: (items: ParsedGearItem[]) => Promise<void>
  onCancel?: () => void
  className?: string
}

export interface ImportState {
  step: 'input' | 'preview' | 'importing' | 'complete'
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors: string[]
  warnings: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
}

export function ImportGearForm({ onImportComplete, onCancel, className }: ImportGearFormProps) {
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('csv')
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    items: [],
    errors: [],
    warnings: []
  })

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    setImportState({
      step: data.length > 0 ? 'preview' : 'input',
      items: data,
      errors,
      warnings,
      metadata
    })
  }

  const handleConfirmImport = async () => {
    setImportState(prev => ({ ...prev, step: 'importing' }))

    try {
      await onImportComplete(importState.items)
      setImportState(prev => ({ ...prev, step: 'complete' }))
    } catch (error) {
      setImportState(prev => ({
        ...prev,
        step: 'preview',
        errors: [...prev.errors, `Import failed: ${error instanceof Error ? error.message : 'Unknown error'}`]
      }))
    }
  }

  const handleReset = () => {
    setImportState({
      step: 'input',
      items: [],
      errors: [],
      warnings: []
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <Card className={className}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CheckCircle className="h-5 w-5 text-green-600" />
            Import Preview
          </CardTitle>
          <CardDescription>
            Review your gear items before importing
            {importState.metadata?.listName && (
              <span className="block font-medium mt-1">{importState.metadata.listName}</span>
            )}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Errors */}
          {importState.errors.length > 0 && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                <div className="font-medium mb-2">Import Errors:</div>
                <ul className="list-disc list-inside space-y-1">
                  {importState.errors.map((error, i) => (
                    <li key={i} className="text-sm">{error}</li>
                  ))}
                </ul>
              </AlertDescription>
            </Alert>
          )}

          {/* Warnings */}
          {importState.warnings.length > 0 && (
            <Alert>
              <Info className="h-4 w-4" />
              <AlertDescription>
                <div className="font-medium mb-2">Warnings:</div>
                <ul className="list-disc list-inside space-y-1">
                  {importState.warnings.map((warning, i) => (
                    <li key={i} className="text-sm">{warning}</li>
                  ))}
                </ul>
              </AlertDescription>
            </Alert>
          )}

          {/* Import Summary */}
          <div className="bg-muted p-4 rounded-lg">
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4 text-sm">
              <div>
                <div className="font-medium">Items to Import</div>
                <div className="text-2xl font-bold text-primary">{importState.items.length}</div>
              </div>
              {importState.metadata?.totalWeight && (
                <div>
                  <div className="font-medium">Total Weight</div>
                  <div className="text-2xl font-bold text-primary">
                    {Math.round(importState.metadata.totalWeight)}g
                  </div>
                </div>
              )}
              <div>
                <div className="font-medium">Categories</div>
                <div className="text-2xl font-bold text-primary">
                  {new Set(importState.items.map(item => item.category)).size}
                </div>
              </div>
            </div>
          </div>

          {/* Item Preview */}
          <div>
            <h4 className="font-medium mb-3">Items Preview (first 5)</h4>
            <div className="space-y-2 max-h-48 overflow-y-auto">
              {importState.items.slice(0, 5).map((item, i) => (
                <div key={i} className="flex items-center justify-between p-2 bg-background border rounded">
                  <div className="flex-1">
                    <div className="font-medium">{item.name}</div>
                    <div className="text-sm text-muted-foreground">
                      {item.category} • {item.weight_grams}g
                      {item.quantity > 1 && ` • Qty: ${item.quantity}`}
                      {item.brand && ` • ${item.brand}`}
                    </div>
                  </div>
                  {item.worn && (
                    <span className="text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded">Worn</span>
                  )}
                  {item.consumable && (
                    <span className="text-xs bg-orange-100 text-orange-800 px-2 py-1 rounded ml-1">Consumable</span>
                  )}
                </div>
              ))}
              {importState.items.length > 5 && (
                <div className="text-center text-sm text-muted-foreground py-2">
                  ... and {importState.items.length - 5} more items
                </div>
              )}
            </div>
          </div>

          {/* Actions */}
          <div className="flex gap-2 pt-4">
            <Button onClick={handleConfirmImport} className="flex-1">
              Import {importState.items.length} Items
            </Button>
            <Button variant="outline" onClick={handleReset}>
              Back to Import
            </Button>
            <Button variant="ghost" onClick={handleClose}>
              Cancel
            </Button>
          </div>
        </CardContent>
      </Card>
    )
  }

  if (importState.step === 'importing' || importState.step === 'complete') {
    return (
      <ImportResults
        state={importState.step}
        importedCount={importState.items.length}
        errors={importState.errors}
        onClose={handleClose}
        onImportMore={handleReset}
        className={className}
      />
    )
  }

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Import Gear</CardTitle>
        <CardDescription>
          Import your gear from LighterPack CSV export or by URL
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="csv" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
          </TabsList>

          <TabsContent value="csv" className="mt-6">
            <CsvImport onImportData={handleImportData} />
          </TabsContent>

          <TabsContent value="url" className="mt-6">
            <UrlImport onImportData={handleImportData} />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-6 pt-4 border-t">
          <Button variant="ghost" onClick={handleClose}>
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

