describe('Import UX Integration', () => {
  const mockOnClose = vi.fn()
  const mockOnImportComplete = vi.fn()

  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('should handle the "all duplicates" scenario with proper feedback', async () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import with all duplicates
    const allDuplicatesButton = await screen.findByText('Import All Duplicates')
    allDuplicatesButton.click()

    // Should show preview (not flicker back to input)
    await waitFor(() => {
      expect(screen.getByText('Import Preview')).toBeInTheDocument()
    })

    // Should show the "all items exist" message
    expect(screen.getByText('All items already exist in your gear library')).toBeInTheDocument()
    expect(screen.getByText(/We found 1 items from your import, but they all match items you already have/)).toBeInTheDocument()

    // Should show "Back to Import" button instead of disabled import
    expect(screen.getByRole('button', { name: /Back to Import/i })).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: /Import.*Items/i })).not.toBeInTheDocument()

    // Should show correct statistics
    expect(screen.getByText('0', { selector: '.text-green-600' })).toBeInTheDocument() // New items
    expect(screen.getByText('1', { selector: '.text-orange-600' })).toBeInTheDocument() // Duplicates
  })

  it('should handle mixed new items and duplicates with clean warnings', async () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import with mixed data
    const mixedDataButton = await screen.findByText('Import Mixed Data (1 new, 1 duplicate)')
    mixedDataButton.click()

    await waitFor(() => {
      expect(screen.getByText('Import Preview')).toBeInTheDocument()
    })

    // Should show summary warning without ugly lists
    expect(screen.getByText('1 items skipped as duplicates (already exist in your gear library)')).toBeInTheDocument()
    expect(screen.getByText('1 new items ready to import')).toBeInTheDocument()

    // Should NOT show individual item listings
    expect(screen.queryByText(/• Skipped:/)).not.toBeInTheDocument()

    // Should show correct import button
    expect(screen.getByRole('button', { name: 'Import 1 New Items' })).toBeInTheDocument()

    // Should show visual separation
    expect(screen.getByText('New Items to Import (first 5)')).toBeInTheDocument()
    expect(screen.getByText('Duplicate Items (will be skipped)')).toBeInTheDocument()
  })

  it('should format heavy weights in kg properly', async () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import with heavy item
    const heavyItemButton = await screen.findByText('Import Heavy Item')
    heavyItemButton.click()

    await waitFor(() => {
      expect(screen.getByText('Import Preview')).toBeInTheDocument()
    })

    // Should show weight in kg format (3500g = 3.50kg)
    expect(screen.getByText('3.50kg')).toBeInTheDocument()
    // Should NOT show the grams version
    expect(screen.queryByText('3500g')).not.toBeInTheDocument()
  })

  it('should provide clear navigation when no items to import', async () => {
    render(
      <ImportGearForm
        onClose={mockOnClose}
        onImportComplete={mockOnImportComplete}
      />
    )

    // Trigger import with all duplicates
    const allDuplicatesButton = await screen.findByText('Import All Duplicates')
    allDuplicatesButton.click()

    await waitFor(() => {
      expect(screen.getByText('Import Preview')).toBeInTheDocument()
    })

    // The main action should be "Back to Import" 
    const backButton = screen.getByRole('button', { name: /Back to Import/i })
    expect(backButton).toBeInTheDocument()
    expect(backButton).toHaveClass('flex-1') // Should be the primary action

    // Should show helpful description
    expect(screen.getByText('No new items to import (all items already exist)')).toBeInTheDocument()
  })
})

