import { describe, it, expect } from 'vitest'
import type { ParsedGearItem } from '@/utils/csvParser'
import type { GearItem } from '@/types/database'
import { formatWeightForDisplay } from '@/utils/weight'

// Test the core UX logic without React components
describe('Import Flow UX Logic', () => {
  // Simulate the deduplication logic from ImportGearForm
  function isDuplicate(importItem: ParsedGearItem, existingItem: GearItem): boolean {
    const importName = importItem.name.toLowerCase().trim()
    const importBrand = (importItem.brand || '').toLowerCase().trim()
    const existingName = existingItem.name.toLowerCase().trim()
    const existingBrand = (existingItem.brand || '').toLowerCase().trim()

    return importName === existingName && importBrand === existingBrand
  }

  function processImportData(
    importItems: ParsedGearItem[], 
    existingItems: GearItem[]
  ) {
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    importItems.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Simulate warning generation (clean, no individual item lists)
    const warnings: string[] = []
    if (duplicates.length > 0) {
      warnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      warnings.push(`${newItems.length} new items ready to import`)
    }

    return { newItems, duplicates, warnings }
  }

  const existingItems: GearItem[] = [
    {
      id: 'existing-1',
      user_id: 'test-user',
      name: 'Osprey Atmos 65',
      brand: 'Osprey',
      weight_grams: 2200,
      category: 'Shelter',
      quantity: 1,
      worn: false,
      consumable: false,
      created_at: '2023-01-01T00:00:00Z',
      notes: null,
      price: null,
      description: null,
      image_url: null
    }
  ]

  describe('All Duplicates Scenario (No Flicker)', () => {
    it('should always show preview even when no new items', () => {
      const importItems: ParsedGearItem[] = [
        {
          name: 'Osprey Atmos 65',
          brand: 'Osprey', 
          weight_grams: 2200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = processImportData(importItems, existingItems)

      // Should detect all duplicates
      expect(result.newItems).toHaveLength(0)
      expect(result.duplicates).toHaveLength(1)

      // Should provide clear feedback
      expect(result.warnings).toContain(
        '1 items skipped as duplicates (already exist in your gear library)'
      )

      // Should NOT contain individual item warnings (clean UX)
      const hasIndividualItemWarnings = result.warnings.some(w => w.includes('• Skipped:'))
      expect(hasIndividualItemWarnings).toBe(false)

      // Key UX improvement: step should be 'preview' not 'input'
      // (This prevents the flicker back to input form)
      const shouldShowPreview = true // Always show preview now
      expect(shouldShowPreview).toBe(true)
    })
  })

  describe('Mixed Items Scenario', () => {
    it('should provide clean summary without ugly lists', () => {
      const importItems: ParsedGearItem[] = [
        // This will be duplicate
        {
          name: 'Osprey Atmos 65',
          brand: 'Osprey',
          weight_grams: 2200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        // This will be new
        {
          name: 'Big Agnes Copper Spur',
          brand: 'Big Agnes',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = processImportData(importItems, existingItems)

      expect(result.newItems).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)

      // Should have clean summary warnings
      expect(result.warnings).toEqual([
        '1 items skipped as duplicates (already exist in your gear library)',
        '1 new items ready to import'
      ])

      // Should NOT have individual item listings
      const hasUglyLists = result.warnings.some(w => w.includes('• Skipped:'))
      expect(hasUglyLists).toBe(false)
    })
  })

  describe('Weight Display Formatting', () => {
    it('should format heavy weights in kg properly', () => {
      // Test weights that were showing poorly before
      expect(formatWeightForDisplay(3500)).toBe('3.50kg') // Heavy pack
      expect(formatWeightForDisplay(9570)).toBe('9.57kg') // Four-pass-loop total
      expect(formatWeightForDisplay(7880)).toBe('7.88kg') // JMT loadout total

      // Should NOT show grams for heavy items
      expect(formatWeightForDisplay(3500)).not.toBe('3500g')
      expect(formatWeightForDisplay(9570)).not.toBe('9570g')
    })

    it('should still show grams for light items', () => {
      expect(formatWeightForDisplay(250)).toBe('250g')
      expect(formatWeightForDisplay(999)).toBe('999g')
    })

    it('should use exactly 1000g as the threshold', () => {
      expect(formatWeightForDisplay(999)).toBe('999g')
      expect(formatWeightForDisplay(1000)).toBe('1.00kg')
      expect(formatWeightForDisplay(1001)).toBe('1.00kg')
    })
  })

  describe('User Experience Improvements', () => {
    it('should provide clear navigation options', () => {
      // When no new items, the primary action should be "Back to Import"
      const allDuplicatesResult = processImportData([
        { name: 'Osprey Atmos 65', brand: 'Osprey', weight_grams: 2200, category: 'Shelter', quantity: 1, worn: false, consumable: false }
      ], existingItems)

      const shouldShowBackToImport = allDuplicatesResult.newItems.length === 0
      expect(shouldShowBackToImport).toBe(true)

      // When there are new items, should show import button
      const mixedResult = processImportData([
        { name: 'New Item', brand: 'New Brand', weight_grams: 500, category: 'Other', quantity: 1, worn: false, consumable: false }
      ], existingItems)

      const shouldShowImportButton = mixedResult.newItems.length > 0
      expect(shouldShowImportButton).toBe(true)
    })

    it('should provide informative descriptions', () => {
      // All duplicates case
      const allDuplicatesResult = processImportData([
        { name: 'Osprey Atmos 65', brand: 'Osprey', weight_grams: 2200, category: 'Shelter', quantity: 1, worn: false, consumable: false }
      ], existingItems)

      expect(allDuplicatesResult.newItems.length).toBe(0)
      expect(allDuplicatesResult.duplicates.length).toBe(1)

      // The description should be: "No new items to import (all items already exist)"
      const descriptionForNoItems = allDuplicatesResult.newItems.length === 0 
        ? 'No new items to import (all items already exist)'
        : `${allDuplicatesResult.newItems.length} new items will be imported`

      expect(descriptionForNoItems).toBe('No new items to import (all items already exist)')
    })
  })
})

